const mockBalance = { success: true, message: 'ok', timestamp: mockNow, total: 1, get_current_balance: [{ balance_in_USD: 7777.77 }] };
const mockTransactions = { data: [] };

function mockTelegram(page: Page) {
  return page.addInitScript(() => {
    (window as any).Telegram = {
      WebApp: {
        initData: '',
        initDataUnsafe: {
          user: {
            id: 64096067,
            first_name: 'Oleksandr',
            last_name: 'Kaiukov',
            username: 'Kaiukov',
            language_code: 'en',
          },
        },
        version: '6.0',
        platform: 'web',
        colorScheme: 'light',
        themeParams: {},
        isExpanded: true,
        viewportHeight: 900,
        viewportStableHeight: 900,
        headerColor: '#ffffff',
        backgroundColor: '#ffffff',
        BackButton: { show() {}, hide() {}, onClick() {} },
        MainButton: { setText() {}, onClick() {}, show() {}, hide() {}, enable() {}, disable() {}, showProgress() {}, hideProgress() {}, isVisible: false, isActive: true, isProgressVisible: false },
        HapticFeedback: { impactOccurred() {}, notificationOccurred() {}, selectionChanged() {} },
        ready() {},
        expand() {},
        close() {},
        showAlert: (message: string) => console.log('Telegram Alert:', message),
        showConfirm: (_msg: string, cb?: (confirmed: boolean) => void) => cb?.(true),
      },
    };
  });
}

async function installApiMocks(page: Page) {
  await page.route('**/api/v1/get_accounts_usage**', (route) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(mockAccounts) }));
  await page.route('**/api/v1/get_destination_name_usage**', (route) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(mockDestinations) }));
  await page.route('**/api/v1/get_exchange_rate**', (route) => {
    const url = new URL(route.request().url());
    const from = url.searchParams.get('from')?.toUpperCase() || 'USD';
    const to = url.searchParams.get('to')?.toUpperCase() || 'EUR';
    const rate = from === to ? 1 : from === 'USD' && to === 'EUR' ? 0.85231 : from === 'EUR' && to === 'USD' ? 1.1736 : 1;
    route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify({ success: true, message: 'ok', timestamp: mockNow, get_exchange_rate: [{ from, to, rate }] }),
    });
  });
  await page.route('**/api/v1/get_running_balance**', (route) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(mockBalance) }));
  await page.route('**/api/v1/transactions**', (route) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(mockTransactions) }));
  await page.route('**/webhook/**', (route) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ ok: true }) }));
}

const srcAmountInput = (page: Page) => page.getByRole('textbox').first();
const dstAmountInput = (page: Page) => page.getByRole('textbox').nth(1);
const sourceFeeInput = (page: Page) => page.getByRole('textbox').first();
const destFeeInput = (page: Page) => page.getByRole('textbox').nth(1);
const destinationInput = (page: Page) => page.getByPlaceholder('Type destination or free text...').first();

test.describe('Transfer flow (mocked, fast)', () => {
  test.beforeEach(async ({ page }) => {
    await mockTelegram(page);
    await installApiMocks(page);
    page.on('dialog', (d) => d.accept().catch(() => {}));
    await page.goto('/');
    await page.waitForSelector('text=Transfer', { timeout: 5000 });
  });

  test('happy path same-currency transfer with mocked data', async ({ page }) => {
    await page.getByText('Transfer').first().click();
    await page.getByText('O PUMB USD').first().click(); // source account
    await page.getByText('CASH USD').first().click(); // destination account (same currency)

    await page.waitForSelector('text=Transfer Amount', { timeout: 3000 });
    await srcAmountInput(page).fill('100');
    await dstAmountInput(page).fill('100');
    await page.getByRole('button', { name: /Next|Continue|→/ }).click();

    await page.waitForSelector('text=Transfer Fees', { timeout: 3000 });
    await sourceFeeInput(page).fill('1');
    await destFeeInput(page).fill('0.5');
    // Verify fees were entered correctly
    await expect(sourceFeeInput(page)).toHaveValue('1');
    await expect(destFeeInput(page)).toHaveValue('0.5');
  });

  test('back button clears amounts when destination account changes (cross currency)', async ({ page }) => {
    await page.getByText('Transfer').first().click();
    await page.getByText('O PUMB USD').first().click(); // source account
    await page.getByText('O PUMP €').first().click(); // destination account (EUR - different currency)

    await page.waitForSelector('text=Transfer Amount', { timeout: 3000 });
    await srcAmountInput(page).fill('120');
    await dstAmountInput(page).fill('102');
    await page.getByRole('button', { name: /Next|Continue|→/ }).click();

    await page.waitForSelector('text=Transfer Fees', { timeout: 3000 });
    await sourceFeeInput(page).fill('1');
    await destFeeInput(page).fill('1');

    // Back to amount screen
    await page.getByRole('button', { name: 'Go back' }).click();
    await page.waitForSelector('text=Transfer Amount', { timeout: 3000 });
    // Verify amounts are preserved
    await expect(srcAmountInput(page)).toHaveValue('120');
    await expect(dstAmountInput(page)).toHaveValue('102');

    // Back to account selection
    await page.getByRole('button', { name: 'Go back' }).click();
    // Wait for page to stabilize
    await page.waitForTimeout(500);

    // Change destination account to same currency as source
    await page.getByText('CASH USD').first().click();

    await page.waitForSelector('text=Transfer Amount', { timeout: 3000 });
    // Amounts should be cleared when destination account changes to same currency
    await expect(srcAmountInput(page)).toHaveValue(/^0?$/);
    await expect(dstAmountInput(page)).toHaveValue(/^0?$/);
  });
});

